open.example:
// client
const menu = kcds.ui.ActionMenu.open(
  {
    entries: [
      { id: 'talk', text: 'Talk' },
      { id: 'trade', text: 'Trade' },
    ],
  },
  (entry) => {
    kcds.core.Events.toServer('market:choose', { entry });
  },
);

open.exampleLua:
-- client
local menu = kcds.ui.ActionMenu.open({
  entries = {
    { id = "talk", text = "Talk" },
    { id = "trade", text = "Trade" },
  },
}, function(entry)
  kcds.core.Events.toServer("market:choose", { entry = entry })
end)

open.exampleCs:
// client
var menu = ActionMenu.Open(new
{
    entries = new[]
    {
        new { id = "talk", text = "Talk" },
        new { id = "trade", text = "Trade" },
    },
}, (string entry) =>
{
    Events.ToServer("market:choose", new { entry });
});

